const fs = require('fs');
const path = require('path');
const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');

const emulatorLib = 'C:\\Users\\12618\\.vela\\sdk\\emulator\\windows-x86_64\\lib';
const definition = protoLoader.loadSync(path.join(emulatorLib, 'emulator_controller.proto'), {
  keepCase: false,
  longs: String,
  enums: String,
  defaults: true,
  oneofs: true,
  includeDirs: [emulatorLib],
});
const api = grpc.loadPackageDefinition(definition).android.emulation.control;
const client = new api.EmulatorController('127.0.0.1:8554', grpc.credentials.createInsecure());

function unary(method, request) {
  return new Promise((resolve, reject) => {
    client[method](request, (error, response) => error ? reject(error) : resolve(response));
  });
}

async function capture(output) {
  const image = await unary('getScreenshot', { format: 'PNG', display: 0 });
  if (!image.image || image.image.length === 0) throw new Error('Emulator returned an empty screenshot');
  fs.mkdirSync(path.dirname(output), { recursive: true });
  fs.writeFileSync(output, image.image);
  process.stdout.write(`${output} ${image.format.width}x${image.format.height} ${image.image.length} bytes\n`);
}

async function tap(x, y) {
  const touch = { x, y, identifier: 1, pressure: 1, touchMajor: 8, touchMinor: 8 };
  await unary('sendTouch', { touches: [touch], display: 0 });
  await new Promise((resolve) => setTimeout(resolve, 120));
  await unary('sendTouch', { touches: [{ ...touch, pressure: 0 }], display: 0 });
}

async function click(x, y) {
  await unary('sendMouse', { x, y, buttons: 1, display: 0 });
  await new Promise((resolve) => setTimeout(resolve, 120));
  await unary('sendMouse', { x, y, buttons: 0, display: 0 });
}

async function series(directory, count, intervalMs) {
  for (let index = 0; index < count; index += 1) {
    await capture(path.join(path.resolve(directory), `frame-${String(index).padStart(2, '0')}.png`));
    if (index + 1 < count) await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
}

async function main() {
  const [action, ...args] = process.argv.slice(2);
  if (action === 'capture') await capture(path.resolve(args[0]));
  else if (action === 'tap') await tap(Number(args[0]), Number(args[1]));
  else if (action === 'click') await click(Number(args[0]), Number(args[1]));
  else if (action === 'series') await series(args[0], Number(args[1]), Number(args[2]));
  else throw new Error('Usage: capture <output.png> | tap <x> <y> | click <x> <y> | series <dir> <count> <interval-ms>');
  client.close();
}

main().catch((error) => {
  console.error(error);
  client.close();
  process.exitCode = 1;
});

